{"path": "/home/centos/triton-ag/_run_032/current/r15_i01_cuda_kernel.py", "content": "import torch
import torch.nn as nn

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        # Matrix dimensions
        N = A.size(0)

        # Create output tensor
        C = torch.zeros(N, N, device=A.device, dtype=A.dtype)

        # Define CUDA kernel
        @torch.jit.script
        def matmul_kernel(A, B, C, N):
            row = torch.ops.prim.blockIdx_y() * torch.ops.prim.blockDim_y() + torch.ops.prim.threadIdx_y()
            col = torch.ops.prim.blockIdx_x() * torch.ops.prim.blockDim_x() + torch.ops.prim.threadIdx_x()

            if row < N and col < N:
                sum_val = 0.0
                for k in range(N):
                    sum_val += A[row, k] * B[k, col]
                C[row, col] = sum_val

        # Configure kernel launch
        threadsPerBlock = (16, 16)
        numBlocks = (
            (N + threadsPerBlock[0] - 1) // threadsPerBlock[0],
            (N + threadsPerBlock[1] - 1) // threadsPerBlock[1]
        )

        # Launch kernel
        matmul_kernel[tuple(numBlocks), tuple(threadsPerBlock)](A, B, C, N)

        return C
"}

