### Iteration 3: Loop Unrolling
We'll unroll the inner loop of the matrix multiplication to reduce branching and improve instruction-level parallelism.

```python
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the optimized CUDA kernel using shared memory and loop unrolling
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 16
#define UNROLL_FACTOR 4

__global__ void matmul_kernel(
    const float* __restrict__ A, 
    const float* __restrict__ B, 
    float* __restrict__ C, 
    int N
) {
    // Shared memory for tiles of A and B
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    // Thread indices
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Block indices
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Calculate row and column of the element to compute
    int row = by * TILE_SIZE + ty;
    int col = bx * TILE_SIZE + tx;

    float sum = 0.0f;

    // Loop over tiles
    int num_tiles = (N + TILE_SIZE - 1) / TILE_SIZE;
    for (int t = 0; t < num_tiles; t += UNROLL_FACTOR) {
        // Preload multiple tiles
        for (int u = 0; u < UNROLL_FACTOR; u++) {
            int t_index = (t + u) * TILE_SIZE;
            int A_col = t_index + tx;
            int B_row = t_index + ty;

            if (row < N && A_col < N) {
                As[ty][tx] = A[row * N + A_col];
            } else {
                As[ty][tx] = 0.0f;
            }

            if (B_row < N && col < N) {
                Bs[ty][tx] = B[B_row * N + col];
            } else {
                Bs[ty][tx] = 0.0f;
            }

            __syncthreads();

            // Compute partial sum with unrolled loop
            #pragma unroll
            for (int k = 0; k < TILE_SIZE; k++) {
                sum += As[ty][k] * Bs[k][tx];
            }

            __syncthreads();
        }
    }

    // Write result to global memory
    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

